 $p->exec("INSERT INTO inventory_items(item_code,name,category,base_unit,active) VALUES('qa-cc15-a','QA CC15 کالا','ingredient','count',1)");$item=(int)$p->lastInsertId();$cat=(string)scalar($p,'SELECT category_key FROM expense_categories WHERE active=1 ORDER BY category_key LIMIT 1');ck($cat!=='','expense category');
