 ck($ws->documentHistory('receipts',['id'=>$rs[0]],$admin)['rows'][0]['total_cost']===null,'unknown purchase cost remains null');$r=$ws->documentHistory('receipts',['id'=>$rs[1]],$bar);ck(!$r['cost_visible']&&!array_key_exists('total_cost',$r['rows'][0]),'restricted receipt cost omitted on server');reject(fn()=>$ws->documentHistory('expenses',[],$bar),'forbidden');reject(fn()=>$c->operationsCommands()->dispatch(['kind'=>'operations.query','operations_remote'=>true,'actor_projection_id'=>'user:'.$bar['id'],'payload'=>['action'=>'expense_history']]),'forbidden');ck(!$p->inTransaction(),'no leaked transaction');$t['costed_receipt']=$rs[1];
